/// <summary>
/// An extension class for GUPPriceRebatePriceAttributeGroupEdit form.
/// </summary>
[ExtensionOf(formStr(GUPPriceRebatePriceAttributeGroupEdit))]
internal final class METGUPPriceRebatePriceAttributeGroupEdit_Extension
{
    internal TAMRebateDeal rebateDeal;

}

Method.Source:
/// <summary>
/// Perform actions at form init
/// </summary>
public void init()
{
    next init();

    TAMRebateTable callerRecord;

    if (this.args().record() && this.args().dataset() == tableNum(TAMRebateTable) && this.args().record().TableId == tablenum(TAMRebateTable))
    {
        callerRecord = this.args().record();
        rebateDeal = TAMRebateDeal::find(callerRecord.RebateDeal);

        if (rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Cust && callerRecord && callerRecord.METTierLineType == METTierLineType::Value)
        {
            GUPPricingRuleConditionCopyHeader_ds.allowEdit(false);
            TAMRebateTable_ds.object(fieldNum(TAMRebateTable, PriceComponentCombination)).allowEdit(false);
        }
    }
}

/// <summary>
/// Get the rebate deal record.
/// </summary>
/// <returns>Returns RebateDeal table record</returns>
public TAMRebateDeal getRebateDeal()
{
    return rebateDeal;
}

/// <summary>
/// Method to determine if the attribute is linked to SalesTable or SalesLine when external sales data is used.
/// </summary>
/// <param name = "_ruleCondition">Active buffer of GUPPricingRuleConditionCopy table</param>
/// <param name = "_attributeSource">Enum element from GUPPricingAttributeSource, either a SalesLine or SalesTable as attribute source</param>
/// <returns>A boolean true, if attribute is not part of SalesTable or SalesLine, else false</returns>
public boolean isAttributeOfSalesTableOrSalesLineValidation(GUPPricingRuleConditionCopy _ruleCondition, GUPPricingAttributeSource _attributeSource)
{
    TAMRebateDeal rebateDealLocal = this.getRebateDeal();
    TAMRebateTable rebateTable = this.dataSource(formDataSourceStr(GUPPriceRebatePriceAttributeGroupEdit, TAMRebateTable)).cursor();

    return _ruleCondition.metValidatePricingRuleConditionValue(_attributeSource, rebateDealLocal, rebateTable);
}
